    --sfa-color-green: #6abf4b;
    --sfa-color-dark-green: #487b32;
    --sfa-color-green-light: #8dce76;
    --sfa-color-green-light-1: #69ad4b;
    --sfa-color-red: #e2231a;
    --sfa-color-red-dark: #941711;
    --sfa-text-black: #000;
    --sfa-color-white: #ffffff;
    --sfa-color-gray-dark: #333333;
    --sfa-color-gray-dark-1: #666666;
    --sfa-color-gray-light-1: #eaeaea;
    --sfa-color-warning-darker: #794d04;
    --sfa-color-alert-warning-border: #ccbea0;
    --sfa-color-alert-warning-bg: #fffaf3;
    --sfa-color-alert-warning-font: #7a4d05;
    --sfa-theme-primary-light-color: #f6fff3;
    --sfa-theme-primary-light-border-color: #bce8ae;
}

.cui[data-theme='dark'] {
    --sfa-theme-primary-color: #6abf4b;
    --sfa-theme-primary-color-dark: #5cad3d;
    --sfa-color-green: #6abf4b;
    --sfa-color-dark-green: #487b32;
    --sfa-color-green-light: #8dce76;
    --sfa-color-green-light-1: #69ad4b;
    --sfa-color-red: #e2231a;
    --sfa-color-red-dark: #941711;
    --sfa-text-black: #000;
    --sfa-color-white: #ffffff;
    --sfa-color-gray-dark: #d3d3d3;
    --sfa-color-gray-dark-1: #ccc;
    --sfa-color-gray-light-1: #eaeaea;
    --sfa-color-warning-darker: #794d04;
    --sfa-theme-primary-light-color: #f6fff3;
    --sfa-theme-primary-light-border-color: #bce8ae;
}

/* Button Primary */
.btn--primary {
    background-color: var(--sfa-color-green) !important;
    border-color: var(--sfa-color-green) !important;
    border-width: 2px !important;
    color: var(--sfa-color-gray-dark) !important;
    font-weight: 700 !important;
}
.btn--primary:hover {
    background-color: var(--sfa-color-green-light) !important;
    border-color: var(--sfa-color-green-light) !important;
    color: var(--sfa-color-gray-dark) !important;
}

.btn--primary.disabled,
.btn--primary[disabled] {
    background-color: var(--cui-color-gray-300) !important;
    border-color: var(--cui-color-gray-300) !important;
    border-style: solid !important;
    color: var(--cui-color-gray-500) !important;
}

.btn--ghost {
    background-color: var(--sfa-color-white) !important;
    border-color: var(--sfa-color-green) !important;
    border-width: 2px !important;
    color: var(--sfa-color-gray-dark) !important;
    font-weight: 700 !important;
}
.btn--ghost:hover {
    background-color: var(--sfa-color-green) !important;
    border-color: var(--sfa-color-green) !important;
    color: var(--sfa-color-gray-dark) !important;
}

.btn--ghost.disabled,
.btn--ghost[disabled] {
    border-color: var(--cui-color-gray-300) !important;
    border-style: solid !important;
    color: var(--cui-color-gray-500) !important;
}

/* Button Ghost */
.cui[data-theme='dark'] {
    .btn--ghost {
        background-color: var(--sfa-color-white) !important;
        border-color: var(--sfa-color-green) !important;
        border-width: 2px !important;
        color: var(--sfa-color-gray-dark) !important;
        font-weight: 700 !important;
    }
    .btn--ghost:hover {
        background-color: var(--sfa-color-green) !important;
        border-color: var(--sfa-color-green) !important;
        color: var(--sfa-color-gray-dark) !important;
    }

    .btn--ghost.disabled,
    .btn--ghost[disabled] {
        border-color: var(--cui-color-gray-300) !important;
        border-style: solid !important;
        color: var(--cui-color-gray-500) !important;
    }
}

/* Button Secondary */
.btn--secondary {
    background-color: var(--sfa-color-gray) !important;
    border-color: var(--sfa-color-gray) !important;
    border-width: 2px !important;
    color: var(--sfa-color-gray-dark) !important;
    font-weight: 700 !important;
}
.btn--secondary:hover {
    background-color: var(--sfa-color-gray-dark) !important;
    border-color: var(--sfa-color-gray-dark) !important;
    color: var(--sfa-color-white) !important;
}
/* Button Danger */
.btn--danger {
    background-color: var(--sfa-color-red) !important;
    border-color: var(--sfa-color-red) !important;
    border-width: 2px !important;
    color: var(--sfa-color-white) !important;
    font-weight: 700 !important;
}
.btn--danger:hover {
    background-color: var(--sfa-color-red-dark) !important;
    border-color: var(--sfa-color-red-dark) !important;
    color: var(--sfa-color-white) !important;
}
/* Button Link */
.btn--link {
    border-radius: 0 !important;
    color: var(--sfa-color-dark-green) !important;
    font-weight: 700 !important;
    padding: 0px !important;
}
.btn--link:disabled,
.btn--link[disabled] {
    border-color: var(--cui-color-gray-300) !important;
    border-style: none !important;
    color: var(--cui-color-gray-500) !important;
}
.btn--link:hover {
    color: var(--sfa-color-green-light) !important;
}
.btn--link:focus {
    box-shadow: none !important;
}

.text-gray-666 {
    color: var(--sfa-color-gray-dark-1) !important;
}
.text-gray-333 {
    color: var(--sfa-color-gray-dark) !important;
}

/* Link*/
.cui a:not(.btn),
.cui .link {
    color: var(--sfa-color-dark-green);
}
.cui a:not(.btn):focus,
.cui a:not(.btn):hover,
.cui .link:focus,
.cui .link:hover {
    color: var(--sfa-color-green-light-1);
}

.sfa_tab .tabs,
.sfa_tab .nav-tabs {
    padding: 0px 8% !important;
}
.sfa_tab .tab-pane.active {
    background-color: var(--cui-color-gray-150) !important;
    padding: 50px 8% !important;
    margin-top: 0px !important;
}
.sfa_tab .tab.active {
    padding: 10px 15px !important;
    border: none !important;
    background-color: var(--cui-color-gray-150) !important;
}
.sfa_tab .tab.active .tabMenu {
    padding: 0px !important;
    background: none !important;
    border: none !important;
    border-bottom: 1px solid var(--sfa-theme-primary-color) !important;
    font-size: 16px !important;
    font-weight: 700 !important;
    box-shadow: none !important;
}
.sfa_tab .tab.active .tabMenu:hover {
    color: var(--cui-active-color) !important;
    box-shadow: none !important;
}
.sfa_tab .tabs > li.active > a,
.cui .tabs > li:hover > a,
.cui .nav-tabs > li.active > a,
.cui .nav-tabs > li:hover > a {
    transition: all var(--cui-animate-speed) var(--cui-animate-timing-function);
    box-shadow: none !important;
    color: var(--cui-active-color) !important;
}
.cui .header ~ .content {
    padding-top: calc(var(--cui-header-height) + var(--notification-bar-height)) !important;
    overflow: unset;
}
