}
.sfa_tab .tab .tabMenu {
    border: none !important;
    background-color: var(--cui-background-color) !important;
    font-size: 16px !important;
    font-weight: 700 !important;
    padding: 0px !important;
}

.sfa_tab .tabs {
    box-shadow: none !important;
}

.b2c_btn {
    border: 2px solid var(--sfa-theme-primary-color) !important;
    background: var(--sfa-theme-primary-color) !important;
    font-weight: 700 !important;
    color: var(--custom-font-color-white) !important;
}
.b2c_btn:hover {
    background-color: var(--sfa-theme-primary-color-dark) !important;
    border: 2px solid var(--sfa-theme-primary-color-dark) !important;
    color: var(--custom-font-color-white) !important;
}
.b2c_btn.disabled,
.b2c_btn[disabled] {
    opacity: 0.5 !important;
}

.b2c_btn_ghost {
    background-color: transparent !important;
    border-color: var(--primary-color) !important;
    border-width: 2px !important;
    color: var(--custom-font-color);
    font-weight: 700 !important;
}
.b2c_btn_ghost:hover {
    background-color: var(--primary-color) !important;
    color: var(--custom-font-color-white) !important;
}
.b2c_btn_ghost.disabled,
.b2c_btn_ghost[disabled] {
    border: 2px solid #ddddde !important;
    background-color: #ddddde !important;
    color: #9ea6b4 !important;
}

.b2c_dropdown input {
    border: 2px solid var(--sfa-theme-primary-color) !important;
    border-radius: 30px !important;
    font-weight: 700 !important;
}

.b2c_dropdown div[role='button']::after {
