    border-radius: var(--cui-border-radius) !important;
    box-shadow: none;
}
.react-select__indicator-separator,
.react-select-recognition__indicator-separator {
    background-color: transparent !important;
}
.react-select__dropdown-indicator svg,
.react-select-recognition__dropdown-indicator svg {
    display: none;
}
.react-select__dropdown-indicator::after,
.react-select-recognition__dropdown-indicator::after {
    transform: rotate(0);
    transition: transform var(--cui-animate-speed) var(--cui-animate-timing-function);
    content: '';
    width: 0;
    height: 0;
    display: inline-flex;
    align-items: center;
    opacity: 1;
    border-radius: 2px;
    border-left: 5px solid transparent;
    border-right: 5px solid transparent;
    border-top: 5px solid var(--cui-font-color);
    position: absolute;
    right: var(--cui-spacing-half);
    top: 0;
    bottom: 0;
    margin: auto;
}
.react-select__control--is-focused .react-select__dropdown-indicator::after,
.react-select-recognition__control--is-focused .react-select-recognition__dropdown-indicator::after {
    transition: transform var(--cui-animate-speed) var(--cui-animate-timing-function);
    transform: rotate(180deg);
}
.react-select__control.react-select__control--is-focused,
.react-select-recognition__control.react-select-recognition__control--is-focused {
    box-shadow: 0 0 0 var(--cui-focus-thickness) rgba(var(--cui-focus-color), var(--cui-focus-opacity));
