    outline: var(--cui-focus-thickness) transparent;
    outline-offset: 1px;
    outline-width: thin;
    outline-style: none;
}
.react-select-recognition__control.react-select-recognition__control--is-focused {
    box-shadow: none;
}
.react-select__menu,
.react-select-recognition__menu {
    background: var(--cui-dropdown-background-color);
    background-color: var(--cui-dropdown-background-color);
    border: var(--cui-border);
    border-top: var(--cui-accent-thickness) solid var(--cui-accent-color);
    color: var(--cui-font-color);
    box-shadow: var(--cui-shadow-outset);
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    border-radius: 0px !important;
}
.react-select__menu-list,
.react-select-recognition__menu-list {
    padding-top: 0px !important;
}
.react-select__option,
.react-select-recognition__option {
    position: relative;
}
.react-select__option.react-select__option--is-focused,
.react-select-recognition__option.react-select-recognition__option--is-focused {
    color: var(--cui-active-color);
