}
.react-select__option.react-select__option--is-selected:after,
.react-select-recognition__option.react-select-recognition__option--is-selected:after {
    content: '';
    background-color: transparent;

    /* position the checkbox */
    position: absolute;
    right: 12px;
    top: 0px;
    width: 4px;
    border-bottom: 2px solid var(--sfa-theme-primary-color);
    /* long arm */
    height: 9px;
    border-right: 2px solid var(--sfa-theme-primary-color);

    /* rotate the mirrored L to make it a checkbox */
    transform: rotate(45deg);
    -o-transform: rotate(45deg);
    -ms-transform: rotate(45deg);
    -webkit-transform: rotate(45deg);
    bottom: 0;
    margin: auto;
}

