    width: auto;
}


#onetrust-banner-sdk a,
#onetrust-pc-sdk a,
#ot-sdk-cookie-policy a,
#onetrust-banner-sdk a {
    color: #0070D2 !important;
    font-size: 14px !important;
    /* font-family: CiscoSansTT; */
    font-weight:400 !important;
    text-decoration: none;
    
    }
    
#onetrust-banner-sdk a:hover {
        color: #0051AF !important;
        cursor: pointer !important;
        text-decoration: none;
    }
    

#onetrust-banner-sdk a::after {
        position: relative;
        content: "";
        display: inline-block;
        width: 0.4em;
        height: 0.4em;
        border-right: 0.1em solid #0070D2;
        border-top: 0.1em solid #0070D2;
        transform: rotate(45deg);
        margin-right: 0.8em;
        margin-left: 0.2em;

    }
    
#onetrust-banner-sdk .ot-close-icon {
    background-image: url(https://www.cisco.com/c/dam/cdc/t/i/icon-close.svg) !important;
}

#onetrust-banner-sdk {
    max-width: 600px;
    min-width: 320px;
    width: auto !important;
    border-width: 1px 1px 0px 0px;
}

#onetrust-banner-sdk #onetrust-policy {
    display: flex;
    margin: 1em 0 0 0;
    width: 100%;
}

#onetrust-banner-sdk .ot-sdk-container {
    margin: 0 16px;
    padding: 0;
    width: auto;
}

#onetrust-banner-sdk #onetrust-group-container {
    width: auto;
}

#onetrust-close-btn-container-mobile {
    float: none;
    order: 2;
}

#onetrust-close-btn-container {
    float: none;
    order: 2;
}

#onetrust-close-btn-container-mobile .onetrust-close-btn-ui {
    float: none;
    padding: 0;
    width: 18px;
    height: 18px;
    background-size: contain;
}

#onetrust-banner-sdk #onetrust-policy-text {
    float: none;
    max-width: 100%;
    /* font-family: CiscoSansTT; */
    font-size: 14px;
    font-weight: 400; 
    color:  #1B1C1D;
    

}
#onetrust-banner-sdk #onetrust-policy-text a {
    font-weight: 400;
    margin-left: 0;
}

#onetrust-banner-sdk .onetrust-close-btn-ui {
    width: 20px;
    height: 20px;
    background-size: contain;
    border: none;
    padding: 0;
    float: none;
    
    
}

#onetrust-banner-sdk #onetrust-button-group-parent {
    display: none;
}

#onetrust-banner-sdk #onetrust-close-btn-container-mobile .onetrust-close-btn-ui {
