        height="0" width="0" style="display:none;visibility:hidden" id="tag-manager"></iframe></noscript><noscript>You need to enable JavaScript to run this app.</noscript><div id="skiplinks"></div><div id="marketplace-container"><div class="tenant"><header class="mastHead--ASif8 header" id="styleguideheader" role="banner"><div class="padRl5--tcene container"><div class="header-panels"><div class="header-panel overlayContainer--m2nIo"><button id="toggle-menu" data-testid="toggle-menu" class="menuIcon--dDbYl half-padding-right btn btn--link"><span class="icon-size-20 icon-list-menu" aria-hidden="true"></span><div class="sr-only">Menu</div></button><a class="header__logo"><img src="/sfa-assets/images/svg/netacad_logo_black.svg" class="netacadLogo--uLVMl" alt="Go to Networking Academy Home" title="Go to Networking Academy Home"></a></div><div class="header-panel header-panel--right"><a type="button" class="header-item text-white base-margin-right"><img src="/sfa-assets/images/svg/search_black.svg" class="searchIconSize--VnNtd" alt="Rechercher dans le catalogue" title="Rechercher dans le catalogue"></a><div class="headerMenuItem--g-f2V"><div class="RBDropdown--FCezN langDropdown--EjJvn dropdown"><button type="button" id="react-aria1565458235-:r0:" aria-expanded="false" aria-label="Sélecteur de langue Français (French)" aria-haspopup="listbox" role="combobox" class="changeLangBtn--ArKu0 btn--link dropdown-toggle btn btn-primary"><div class="flex flex-middle"><img src="/sfa-assets/images/svg/globe_black.svg" class="headerIconSize--pVU51 globalIconGrey--O1yCr" alt="Change language" aria-hidden="true"><img src="/sfa-assets/images/svg/globe_green.svg" class="headerIconSize--pVU51 globeIconGreen--967sc" alt="Change language" aria-hidden="true"><div class="languageCode--WGBmj">FR</div></div></button></div></div><a class="header-item text-white no-margin"><img src="/sfa-assets/images/svg/user.svg" class="userProfileImg--d8Bo+" alt="header.login" title="header.login"></a></div></div></div></header><div style="display: none;">&nbsp;</div><main class="content" id="main-content"><div class="sectionBannerBg--9PRSR"><div class="row"><div class="col-lg-6 order-lg-2 flex"><img src="/sfa-assets/images/png/landingBannerImage.png" class="sectionBannerImg--daIjS" alt="" loading="lazy"></div><div class="col-lg-6 order-lg-1 positionUnset--vTbxS"><div class="marketBanner--ezof8"><div class="flex flex-middle"><img src="/sfa-assets/images/svg/fire.svg" class="fireIcon--Ig4GS" alt="" loading="lazy"><div class=""><div class="mBtitle--oi6HG">Le marché de l'emploi de la cybersécurité recrute à tour de bras&nbsp;!</div><div class="mBdesc--pUSeD">Découvrez pourquoi 5&nbsp;millions de personnes se sont inscrites à notre <a href="/fr/courses/introduction-to-cybersecurity?courseLang=fr-FR">cours gratuit Intro to Cybersecurity</a></div></div></div></div><h1 class="sectionTitle--utbL0">Gagnez des compétences <br> et décrochez l'emploi de vos rêves.</h1><p class="sectionDesc--n1FGD">Cours en ligne gratuits. Formations en présentiel. Parcours menant à des certifications sur des sujets tels que la cybersécurité, les réseaux et le langage Python.</p><p class="sectionDesc--n1FGD">Tout est là. Êtes-vous prêt à démarrer, à réorienter ou à relancer votre carrière&nbsp;?</p><div class="flex flex-middle flex-wrap"><div class="bannerCtaBlcok--0gnzX"><a class="btn btn--primary btn--large btn--justified" href="/fr/catalogs/learn">Démarrer votre formation</a></div><div class="bannerCtaBlcok--0gnzX"><button type="button" class="btn btn--ghost btn--large btn--justified">Explorer les thèmes</button></div></div></div></div></div><div class="bannerWrapper--nW+Zt"><div class="sfa_stats_banner--kNGx9"><div class="sfa_stats_bannerRow--V2uXA"><div class="stats_item--0jIyp"><div class="stats_title--jt+Et">24 millions</div><div class="stats_desc--77xXj">d'élèves depuis nos débuts en 1997</div></div><div class="flex flex-middle flex-center"><span class="stats_separator--nM-vQ"></span></div><div class="stats_item--0jIyp"><div class="stats_title--jt+Et">31 300</div><div class="stats_desc--77xXj">formateurs dans le monde entier</div></div><div class="flex flex-middle flex-center"><span class="stats_separator--nM-vQ"></span></div><div class="stats_item--0jIyp"><div class="stats_title--jt+Et">12 100</div><div class="stats_desc--77xXj">entreprises qui proposent nos cours</div></div><div class="flex flex-middle flex-center"><span class="stats_separator--nM-vQ"></span></div><div class="stats_item--0jIyp"><div class="stats_title--jt+Et">191</div><div class="stats_desc--77xXj">pays où nous formons des élèves</div></div><div class="flex flex-middle flex-center"><span class="stats_separator--nM-vQ"></span></div><div class="stats_item--0jIyp"><div class="stats_title--jt+Et">96%</div><div class="stats_desc--77xXj">Les étudiants ont obtenu une opportunité de carrière et/ou de formation.<sup class="superScriptNumber--tk1iF">1</sup></div></div></div></div></div><section class="sectionQuote--SaEE4"><div class="quoteContentBlock--WQ7Ji"><div class="quoteIconBorder--3NYBo"><img src="/sfa-assets/images/svg/icon-quote-left.svg" class="quoteIcon--dwBVU" loading="lazy" alt="quote"></div><h2 class="quoteTitle--IfH89">4,3&nbsp;millions d'étudiants déclarent que la Cisco&nbsp;Networking&nbsp;Academy les a aidés à décrocher un emploi. <sup class="superScriptNumber--tk1iF">4</sup></h2><span class="horizontalSeparator--cGrwZ"></span><p class="text-size-16 text-weight-400">Parcourez les domaines ci-dessous pour vous ouvrir de nouveaux horizons.</p></div></section><section class="sectionSubjectArea--fR+kx"><div class="sectionTitle--utbL0">Domaines</div><div class="subjectAreaBlock--asxt8"><a class="subjectAreaCard---CmgY" href="/fr/cybersecurity"><img src="/sfa-assets/images/svg/sa-cybersecurity.svg" class="subjectAreaIcon--A2Z6+" alt="subject area icon"><div class="subjectAreaTitle--vXBAJ">Cybersécurité</div></a><a class="subjectAreaCard---CmgY" href="/fr/networking"><img src="/sfa-